import 'package:flutter/material.dart';
import 'package:fluttertoast/fluttertoast.dart';

class BasicToastExample extends StatelessWidget {
  const BasicToastExample({super.key});

  void _showToast() {
    Fluttertoast.showToast(
      msg: '저장되었습니다!',
      toastLength: Toast.LENGTH_SHORT, // SHORT (2초) 또는 LONG (3.5초)
      gravity: ToastGravity.BOTTOM, // 표시 위치
      backgroundColor: Colors.black87,
      textColor: Colors.white,
      fontSize: 16.0,
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Toast 기본')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            ElevatedButton(
              onPressed: _showToast,
              child: const Text('Toast 표시'),
            ),
            const SizedBox(height: 20),
            ElevatedButton(
              onPressed: () {
                Fluttertoast.showToast(
                  msg: '상단에 표시됩니다',
                  gravity: ToastGravity.TOP,
                );
              },
              child: const Text('상단 Toast'),
            ),
            const SizedBox(height: 20),
            ElevatedButton(
              onPressed: () {
                Fluttertoast.showToast(
                  msg: '가운데 표시됩니다',
                  gravity: ToastGravity.CENTER,
                );
              },
              child: const Text('중앙 Toast'),
            ),
            const SizedBox(height: 20),
            ElevatedButton(
              onPressed: () {
                Fluttertoast.showToast(
                  msg: '긴 메시지입니다',
                  toastLength: Toast.LENGTH_LONG,
                );
              },
              child: const Text('긴 Toast'),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:fluttertoast/fluttertoast.dart';

class CustomToastExample extends StatefulWidget {
  const CustomToastExample({super.key});

  @override
  State<CustomToastExample> createState() => _CustomToastExampleState();
}

class _CustomToastExampleState extends State<CustomToastExample> {
  late FToast fToast;

  @override
  void initState() {
    super.initState();
    fToast = FToast();
    fToast.init(context);
  }

  void _showSuccessToast() {
    fToast.showToast(
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 12),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(25),
          color: Colors.green,
        ),
        child: const Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(Icons.check, color: Colors.white),
            SizedBox(width: 12),
            Text(
              '성공적으로 저장되었습니다!',
              style: TextStyle(color: Colors.white),
            ),
          ],
        ),
      ),
      gravity: ToastGravity.BOTTOM,
      toastDuration: const Duration(seconds: 2),
    );
  }

  void _showErrorToast() {
    fToast.showToast(
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 12),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(25),
          color: Colors.red,
        ),
        child: const Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(Icons.error, color: Colors.white),
            SizedBox(width: 12),
            Text(
              '오류가 발생했습니다',
              style: TextStyle(color: Colors.white),
            ),
          ],
        ),
      ),
      gravity: ToastGravity.TOP,
      toastDuration: const Duration(seconds: 3),
    );
  }

  void _showWarningToast() {
    fToast.showToast(
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 12),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(12),
          color: Colors.orange,
          boxShadow: [
            BoxShadow(
              color: Colors.black.withOpacity(0.2),
              blurRadius: 10,
              offset: const Offset(0, 5),
            ),
          ],
        ),
        child: const Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(Icons.warning, color: Colors.white),
            SizedBox(width: 12),
            Text(
              '네트워크 연결을 확인하세요',
              style: TextStyle(color: Colors.white, fontWeight: FontWeight.bold),
            ),
          ],
        ),
      ),
      gravity: ToastGravity.CENTER,
      toastDuration: const Duration(seconds: 2),
    );
  }

  void _showInfoToast() {
    fToast.showToast(
      child: Container(
        padding: const EdgeInsets.all(16),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(12),
          color: Colors.white,
          border: Border.all(color: Colors.blue, width: 2),
        ),
        child: const Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(Icons.info, color: Colors.blue),
            SizedBox(width: 12),
            Text(
              '새로운 업데이트가 있습니다',
              style: TextStyle(color: Colors.blue),
            ),
          ],
        ),
      ),
      gravity: ToastGravity.BOTTOM,
      toastDuration: const Duration(seconds: 3),
    );
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('커스텀 Toast')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            ElevatedButton.icon(
              onPressed: _showSuccessToast,
              icon: const Icon(Icons.check),
              label: const Text('성공 Toast'),
              style: ElevatedButton.styleFrom(backgroundColor: Colors.green),
            ),
            const SizedBox(height: 16),
            ElevatedButton.icon(
              onPressed: _showErrorToast,
              icon: const Icon(Icons.error),
              label: const Text('오류 Toast'),
              style: ElevatedButton.styleFrom(backgroundColor: Colors.red),
            ),
            const SizedBox(height: 16),
            ElevatedButton.icon(
              onPressed: _showWarningToast,
              icon: const Icon(Icons.warning),
              label: const Text('경고 Toast'),
              style: ElevatedButton.styleFrom(backgroundColor: Colors.orange),
            ),
            const SizedBox(height: 16),
            ElevatedButton.icon(
              onPressed: _showInfoToast,
              icon: const Icon(Icons.info),
              label: const Text('정보 Toast'),
              style: ElevatedButton.styleFrom(backgroundColor: Colors.blue),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:fluttertoast/fluttertoast.dart';

enum ToastType { success, error, warning, info }

class ToastHelper {
  static final FToast _fToast = FToast();

  static void init(BuildContext context) {
    _fToast.init(context);
  }

  static void show({
    required String message,
    ToastType type = ToastType.info,
    ToastGravity gravity = ToastGravity.BOTTOM,
    Duration duration = const Duration(seconds: 2),
  }) {
    final config = _getConfig(type);

    _fToast.showToast(
      child: Container(
        padding: const EdgeInsets.symmetric(horizontal: 20, vertical: 12),
        decoration: BoxDecoration(
          borderRadius: BorderRadius.circular(8),
          color: config['backgroundColor'] as Color,
          boxShadow: [
            BoxShadow(
              color: Colors.black.withOpacity(0.15),
              blurRadius: 8,
              offset: const Offset(0, 3),
            ),
          ],
        ),
        child: Row(
          mainAxisSize: MainAxisSize.min,
          children: [
            Icon(
              config['icon'] as IconData,
              color: Colors.white,
              size: 20,
            ),
            const SizedBox(width: 10),
            Flexible(
              child: Text(
                message,
                style: const TextStyle(
                  color: Colors.white,
                  fontSize: 14,
                ),
              ),
            ),
          ],
        ),
      ),
      gravity: gravity,
      toastDuration: duration,
    );
  }

  static Map<String, dynamic> _getConfig(ToastType type) {
    switch (type) {
      case ToastType.success:
        return {
          'backgroundColor': Colors.green,
          'icon': Icons.check_circle,
        };
      case ToastType.error:
        return {
          'backgroundColor': Colors.red,
          'icon': Icons.error,
        };
      case ToastType.warning:
        return {
          'backgroundColor': Colors.orange,
          'icon': Icons.warning,
        };
      case ToastType.info:
        return {
          'backgroundColor': Colors.blue,
          'icon': Icons.info,
        };
    }
  }

  // 간편 메서드
  static void success(String message) =>
      show(message: message, type: ToastType.success);

  static void error(String message) =>
      show(message: message, type: ToastType.error, gravity: ToastGravity.TOP);

  static void warning(String message) =>
      show(message: message, type: ToastType.warning);

  static void info(String message) =>
      show(message: message, type: ToastType.info);

  // 네이티브 Toast (간단한 메시지용)
  static void showNative(String message) {
    Fluttertoast.showToast(
      msg: message,
      toastLength: Toast.LENGTH_SHORT,
      gravity: ToastGravity.BOTTOM,
      backgroundColor: Colors.black87,
      textColor: Colors.white,
    );
  }

  // 현재 Toast 취소
  static void cancel() {
    _fToast.removeCustomToast();
  }

  // 모든 Toast 제거
  static void removeAll() {
    _fToast.removeQueuedCustomToasts();
  }
}

// 사용 예시
class ToastHelperUsage extends StatefulWidget {
  const ToastHelperUsage({super.key});

  @override
  State<ToastHelperUsage> createState() => _ToastHelperUsageState();
}

class _ToastHelperUsageState extends State<ToastHelperUsage> {
  @override
  void initState() {
    super.initState();
    // 위젯 빌드 후 초기화
    WidgetsBinding.instance.addPostFrameCallback((_) {
      ToastHelper.init(context);
    });
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Toast Helper')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            ElevatedButton(
              onPressed: () => ToastHelper.success('저장되었습니다!'),
              child: const Text('성공'),
            ),
            const SizedBox(height: 12),
            ElevatedButton(
              onPressed: () => ToastHelper.error('오류가 발생했습니다'),
              child: const Text('오류'),
            ),
            const SizedBox(height: 12),
            ElevatedButton(
              onPressed: () => ToastHelper.warning('주의가 필요합니다'),
              child: const Text('경고'),
            ),
            const SizedBox(height: 12),
            ElevatedButton(
              onPressed: () => ToastHelper.info('새 메시지가 있습니다'),
              child: const Text('정보'),
            ),
          ],
        ),
      ),
    );
  }
}

import 'package:flutter/material.dart';
import 'package:fluttertoast/fluttertoast.dart';

class ToastQueueExample extends StatefulWidget {
  const ToastQueueExample({super.key});

  @override
  State<ToastQueueExample> createState() => _ToastQueueExampleState();
}

class _ToastQueueExampleState extends State<ToastQueueExample> {
  late FToast fToast;

  @override
  void initState() {
    super.initState();
    fToast = FToast();
    fToast.init(context);
  }

  // 여러 Toast를 연속으로 표시 (큐에 쌓임)
  void _showMultipleToasts() {
    for (int i = 1; i <= 5; i++) {
      fToast.showToast(
        child: Container(
          padding: const EdgeInsets.symmetric(horizontal: 24, vertical: 12),
          decoration: BoxDecoration(
            borderRadius: BorderRadius.circular(8),
            color: Colors.primaries[i * 2],
          ),
          child: Text(
            'Toast $i',
            style: const TextStyle(color: Colors.white),
          ),
        ),
        toastDuration: const Duration(seconds: 2),
      );
    }
  }

  // 현재 Toast 취소
  void _cancelCurrentToast() {
    fToast.removeCustomToast();
  }

  // 큐의 모든 Toast 취소
  void _cancelAllToasts() {
    fToast.removeQueuedCustomToasts();
  }

  @override
  Widget build(BuildContext context) {
    return Scaffold(
      appBar: AppBar(title: const Text('Toast 큐 관리')),
      body: Center(
        child: Column(
          mainAxisAlignment: MainAxisAlignment.center,
          children: [
            ElevatedButton(
              onPressed: _showMultipleToasts,
              child: const Text('5개 Toast 표시'),
            ),
            const SizedBox(height: 20),
            ElevatedButton(
              onPressed: _cancelCurrentToast,
              child: const Text('현재 Toast 취소'),
            ),
            const SizedBox(height: 20),
            ElevatedButton(
              onPressed: _cancelAllToasts,
              child: const Text('모든 Toast 취소'),
            ),
            const SizedBox(height: 40),
            // 네이티브 Toast 취소
            ElevatedButton(
              onPressed: () {
                Fluttertoast.showToast(msg: '네이티브 Toast');
              },
              child: const Text('네이티브 Toast'),
            ),
            const SizedBox(height: 20),
            ElevatedButton(
              onPressed: () {
                Fluttertoast.cancel();
              },
              child: const Text('네이티브 Toast 취소'),
            ),
          ],
        ),
      ),
    );
  }
}
